# Checkout Component Test Suite

The user should feel as welcome as a knight at the Round Table. Let us craft tests that honor both function and grace.

```typescript
// Checkout.test.tsx
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Arrange: Mock contexts with courtly precision
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockOnComplete = vi.fn();
const mockOnCancel = vi.fn();

const mockCartItems = [
  { id: '1', name: 'Excalibur Replica', price: 299.99 },
  { id: '2', name: 'Round Table Coaster Set', price: 24.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: mockCartItems,
    total: 324.98,
    clearCart: mockClearCart
  })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

const validShipping = {
  street: '1 Camelot Way',
  city: 'Avalon',
  state: 'CA',
  zip: '90210'
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'Sir Lancelot'
};

describe('Checkout - Happy Path', () => {
  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-CAMELOT-001' });

    render(<Checkout onComplete={mockOnComplete} onCancel={mockOnCancel} />);

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), validShipping.street);
    await user.type(screen.getByLabelText(/city/i), validShipping.city);
    await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
    await user.type(screen.getByLabelText(/zip/i), validShipping.zip);
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
    await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
    await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
    await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/excalibur replica/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
    expect(screen.getByText('ORD-CAMELOT-001')).toBeInTheDocument();
    expect(mockOnComplete).toHaveBeenCalledWith('ORD-CAMELOT-001');
  });
});

describe('Checkout - Form Validation', () => {
  it('displays error when ZIP code format is invalid', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.type(screen.getByLabelText(/zip/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code/i);
    expect(screen.getByLabelText(/zip/i)).toHaveAttribute('aria-invalid', 'true');
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message and allows navigation away', async () => {
    vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });

    render(<Checkout onCancel={mockOnCancel} />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });
});

describe('Checkout - Accessibility', () => {
  it('has no accessibility violations on shipping form', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
```

